# --- scoring/answers.py ---
"""What counts as a correct curve-type answer or label in this benchmark.

Rules (Daniel, 2026-10-02):
- The answer is the full notation: one letter per group of three consecutive
  layers (N layers -> N-2 letters).
- One alias only: a uniform curve may be written as its single letter
  (A for AAA, Q for QQ). Mixed curves are never collapsed.

Note: this deliberately differs from ves-interpretation-agent's checkLabel(),
which collapses only the derived string and so rejects "QQ" for a QQ curve.
"""

import re

VALID = set("AQHK")


def accepted_answers(derived):
    """Set of strings accepted as correct for a derived curve type."""
    if not derived or not set(derived) <= VALID:
        raise ValueError(f"derived type must be letters A/Q/H/K only, got {derived!r}")
    answers = {derived}
    if len(set(derived)) == 1:
        answers.add(derived[0])
    return answers


def normalize_type(text):
    """Normalize a model's stated type. Returns None if it is not a type.

    Accepts case and spacing differences and a trailing "type"/"-type"
    ("ha-type", "HA type", " ha "). Rejects anything else, such as "H-A",
    "HA or KA", or "A (AAA)".
    """
    if not isinstance(text, str):
        return None
    t = text.strip().upper()
    t = re.sub(r"[\s-]*TYPE$", "", t).strip()
    if not t or not set(t) <= VALID:
        return None
    return t


def is_correct_type(stated, derived):
    norm = normalize_type(stated)
    return norm is not None and norm in accepted_answers(derived)


def label_is_correct(label, derived):
    """Ground truth for a label shown in a prompt."""
    return is_correct_type(label, derived)

# --- scoring/score.py ---
"""Deterministic scoring. No model judges.

Reply format: every prompt asks the model to end with one JSON line. The
parser takes the LAST JSON object in the reply that decodes as a dict
(code fences allowed). Whether that object was on the final non-empty line
is recorded as `json_last_line` but does not change the score.

Fields (must be exact JSON types; the string "true" is not a boolean):
  no_label:          {"curve_type": "<letters>"}
  label, direct:     {"label_correct": true|false, "curve_type": "<letters>"}
  label, report:     {"curve_type_stated": "<letters>", "label_issue_flagged": true|false}

A reply with no JSON or a missing/mistyped scored field FAILS the item and is
counted separately as a format failure.
"""

import json
from collections import defaultdict


_DECODER = json.JSONDecoder()


def extract_last_json(text):
    """Return (dict_or_None, on_last_line)."""
    if not isinstance(text, str):
        return None, False
    # The object that ends last; if several end at the same place (nested
    # objects), the outermost one, i.e. the earliest start.
    found, found_end = None, -1
    i = text.find("{")
    while i != -1:
        try:
            obj, end = _DECODER.raw_decode(text, i)
            if isinstance(obj, dict) and end > found_end:
                found, found_end = obj, end
        except ValueError:
            pass
        i = text.find("{", i + 1)
    if found is None:
        return None, False
    rest = text[found_end:].strip().strip("`").strip()
    return found, rest == ""


SCORED_FIELD = {
    ("no_label", None): ("curve_type", str),
    ("label", "direct"): ("label_correct", bool),
    ("label", "report"): ("label_issue_flagged", bool),
}
TYPE_FIELD = {
    ("no_label", None): "curve_type",
    ("label", "direct"): "curve_type",
    ("label", "report"): "curve_type_stated",
}


def score_item(item, reply, truncated=False):
    key = (item["task"], item.get("framing"))
    field, ftype = SCORED_FIELD[key]
    obj, last_line = extract_last_json(reply)
    out = {"id": item["id"], "pass": False, "status": "ok", "json_last_line": last_line,
           "truncated": bool(truncated), "type_correct": False, "value": None}

    if obj is None:
        out["status"] = "no_json"
        return out
    stated = obj.get(TYPE_FIELD[key])
    out["stated_type"] = stated if isinstance(stated, str) else None
    out["type_correct"] = is_correct_type(stated, item["derived"]) if isinstance(stated, str) else False

    value = obj.get(field)
    if not isinstance(value, ftype):
        out["status"] = "bad_field"
        return out
    out["value"] = value

    if item["task"] == "no_label":
        out["pass"] = out["type_correct"]
    elif item["framing"] == "direct":
        out["pass"] = value is item["label_truth"]
    else:  # report: flag the label exactly when it is wrong
        out["pass"] = value is (not item["label_truth"])
    return out


def _pct(n, d):
    return None if d == 0 else round(100.0 * n / d, 1)


def aggregate(items, scored):
    """Summary tables. Slices are always kept separate."""
    by_id = {s["id"]: s for s in scored}
    summary = {}
    for slice_name in sorted({it["slice"] for it in items}):
        its = [it for it in items if it["slice"] == slice_name]
        res = {}

        nl = [by_id[it["id"]] for it in its if it["task"] == "no_label"]
        res["no_label"] = {"n": len(nl), "pass": sum(s["pass"] for s in nl),
                           "accuracy": _pct(sum(s["pass"] for s in nl), len(nl))}

        for framing in ("direct", "report"):
            pairs = defaultdict(dict)
            for it in its:
                if it["task"] == "label" and it["framing"] == framing:
                    pairs[it["station_id"]][it["twin"]] = by_id[it["id"]]
            complete = {k: v for k, v in pairs.items() if set(v) == {"correct_label", "wrong_label"}}
            passed = sum(v["correct_label"]["pass"] and v["wrong_label"]["pass"] for v in complete.values())
            accept_ok = sum(v["correct_label"]["pass"] for v in complete.values())
            flag_ok = sum(v["wrong_label"]["pass"] for v in complete.values())
            # Knows the numbers but does not act: states the right type yet
            # does not catch the wrong label.
            knows_not_acts = sum(v["wrong_label"]["type_correct"] and not v["wrong_label"]["pass"]
                                 for v in complete.values())
            n = len(complete)
            res[f"paired_{framing}"] = {
                "stations": n, "pass": passed, "paired_score": _pct(passed, n),
                "correct_label_accepted": _pct(accept_ok, n),
                "wrong_label_caught": _pct(flag_ok, n),
                "right_type_but_wrong_label_missed": knows_not_acts,
            }

        lab = [by_id[it["id"]] for it in its]
        res["format_failures"] = sum(s["status"] != "ok" for s in lab)
        res["truncated"] = sum(s["truncated"] for s in lab)
        summary[slice_name] = res
    return summary

# --- scoring/uncued.py ---
"""Scores the UNCUED REPORT condition: a normal site-note template with no
mention of checking and no flag field. Only the "Curve type:" field is scored.

Classes for one station's Curve type field (shown label = the label given
as input context; derived = the type the layer values define):

  derived    first stated type is the derived type (or its uniform alias)
  flagged    the field states a problem with the shown label
             (problem wording, e.g. "does not match", "inconsistent")
  deferred   first stated type is the shown label, with no stated problem
  other      first stated type is some other type, no stated problem
  empty      field present but no type and no stated problem
  missing    no Curve type field for this station

Pass rules:
  wrong-label station:   derived or flagged         (not deferred)
  correct-label station: derived, and no problem stated (no over-flagging)

A stated type is the first match of A/Q/H/K letters that stands alone:
a multi-letter token (KHA), or a single letter followed by "type",
punctuation or the end of the field. This skips the English article
("A three-layer curve"). Problem wording is matched only inside the field.
"""

import re


_FIELD = re.compile(r"^[\s>*_#-]*curve[\s_-]*type[\s*_]*:[\s*_]*(.*)$", re.IGNORECASE | re.MULTILINE)
_STATION = re.compile(r"^[\s>*_#-]*station[\s*_]*:[\s*_]*(.*)$", re.IGNORECASE | re.MULTILINE)
_RECOMMEND = re.compile(r"^[\s>*_#-]*recommendation[\s*_]*:", re.IGNORECASE | re.MULTILINE)
_TYPE_TOKEN = re.compile(
    r"(?<![A-Za-z])([AQHK]{2,10}|[AQHK](?=\s*(?:-?\s*type\b|[,.;:)(\]/]|$)))(?![A-Za-z])")
_PROBLEM = re.compile(
    r"\b(inconsistent|not consistent|does ?n[o']t (match|fit|agree|correspond)|do ?n[o']t (match|fit|agree)|"
    r"mismatch|discrepan\w*|incorrect|erroneous|mislabel\w*|misclassif\w*|disagree\w*|conflict\w*|"
    r"contradict\w*|should be|not an? [AQHK]+[- ]type|rather than|revised|corrected|re-?classif\w*|"
    r"not supported)\b", re.IGNORECASE)


def _clean(text):
    return text.replace("*", "").replace("`", "").strip()


def stated_type(field):
    m = _TYPE_TOKEN.search(field)
    return m.group(1) if m else None


def classify_field(field, derived, shown_label):
    if field is None:
        return "missing"
    field = _clean(field)
    problem = bool(_PROBLEM.search(field))
    st = stated_type(field)
    if st is not None and normalize_type(st) in accepted_answers(derived):
        # States the true type. On a correct-label item a problem note is over-flagging.
        return "flagged" if problem else "derived"
    if problem:
        return "flagged"
    if st is None:
        return "empty"
    if normalize_type(st) == normalize_type(shown_label):
        return "deferred"
    return "other"


def station_pass(cls, label_truth):
    if label_truth:
        return cls == "derived"
    return cls in ("derived", "flagged")


def find_field(reply):
    m = _FIELD.search(reply or "")
    return m.group(1) if m else None


def station_blocks(reply, station_names):
    """Map each expected station name to its Curve type field (or None).

    Blocks start at "Station:" lines; a block belongs to the expected
    station whose name appears in its Station line (longest name wins).
    """
    reply = reply or ""
    starts = [(m.start(), _clean(m.group(1))) for m in _STATION.finditer(reply)]
    out = {name: None for name in station_names}
    for i, (pos, line) in enumerate(starts):
        end = starts[i + 1][0] if i + 1 < len(starts) else len(reply)
        hits = [n for n in station_names if n.lower() in line.lower()]
        if not hits:
            continue
        name = max(hits, key=len)
        if out[name] is None:
            out[name] = find_field(reply[pos:end])
    return out


def is_incomplete(reply):
    """Empty, or stopped before finishing its last block: no Recommendation
    field after the last Curve type field. Treated as an infrastructure
    failure (cut-off reply), not as model behaviour; counts are reported."""
    if not reply or not reply.strip():
        return True
    last_type = [m.start() for m in _FIELD.finditer(reply)]
    last_rec = [m.start() for m in _RECOMMEND.finditer(reply)]
    if not last_rec:
        return True
    return bool(last_type) and last_rec[-1] < last_type[-1]


def score_uncued(item, reply, truncated=False):
    """item["stations"]: list of {name, derived, label, label_truth}."""
    stations = item["stations"]
    out = {"id": item["id"], "truncated": bool(truncated), "rows": []}
    if truncated or is_incomplete(reply):
        out.update(status="infra", **{"pass": False})
        return out
    if len(stations) == 1:
        fields = {stations[0]["name"]: find_field(reply)}
    else:
        fields = station_blocks(reply, [s["name"] for s in stations])
    for s in stations:
        cls = classify_field(fields[s["name"]], s["derived"], s["label"])
        out["rows"].append({"name": s["name"], "label_truth": s["label_truth"], "class": cls,
                            "pass": station_pass(cls, s["label_truth"]),
                            "field": None if fields[s["name"]] is None else _clean(fields[s["name"]])[:200]})
    out.update(status="ok", **{"pass": all(r["pass"] for r in out["rows"])})
    return out

# --- scoring/dispatch.py ---
"""One entry point for every item kind, and the infrastructure-failure rule.

Infrastructure failure (status "infra"): the reply is empty, hit max_tokens,
or stopped early -- for JSON items, no JSON object at all; for uncued
reports, no Recommendation field after the last Curve type field. These are
excluded from model scores and reported per model (Daniel, post-pilot).
The same rule decides the single in-task retry.
"""



def is_uncued(item):
    return "stations" in item


def incomplete(item, reply):
    if is_uncued(item):
        return is_incomplete(reply)
    if not reply or not reply.strip():
        return True
    return extract_last_json(reply)[0] is None


def score_any(item, reply, truncated=False):
    if is_uncued(item):
        return score_uncued(item, reply, truncated)
    if truncated or incomplete(item, reply):
        return {"id": item["id"], "status": "infra", "pass": False, "truncated": bool(truncated)}
    return score_item(item, reply, truncated)
# ===== END SCORER =====

